import re

def parse_json(json_str):
    def parse_value(value):
        if value == 'true':
            return True
        elif value == 'false':
            return False
        elif value == 'null':
            return None
        elif re.match(r'^-?\d+(\.\d+)?$', value):
            return float(value) if '.' in value else int(value)
        elif value.startswith('"') and value.endswith('"'):
            return value[1:-1].replace('\\"', '"').replace('\\n', '\n').replace('\\t', '\t').replace('\\b', '\b').replace('\\f', '\f').replace('\\r', '\r')
        else:
            raise ValueError("Invalid JSON value")

    def parse_object():
        if json_str[0] != '{':
            raise ValueError("Expected '{'")
        json_str = json_str[1:]
        obj = {}
        while json_str[0] != '}':
            key = parse_string()
            if json_str[0] != ':':
                raise ValueError("Expected ':'")
            json_str = json_str[1:]
            value = parse_value(parse_token())
            obj[key] = value
            if json_str[0] == ',':
                json_str = json_str[1:]
            else:
                break
        if json_str[0] != '}':
            raise ValueError("Expected '}'")
        return obj

    def parse_array():
        if json_str[0] != '[':
            raise ValueError("Expected '['")
        json_str = json_str[1:]
        arr = []
        while json_str[0] != ']':
            value = parse_value(parse_token())
            arr.append(value)
            if json_str[0] == ',':
                json_str = json_str[1:]
            else:
                break
        if json_str[0] != ']':
            raise ValueError("Expected ']'")
        return arr

    def parse_string():
        if json_str[0] != '"':
            raise ValueError("Expected '\"'")
        json_str = json_str[1:]
        result = ''
        while json_str[0] != '"':
            if json_str[0] == '\\':
                json_str = json_str[1:]
                if json_str[0] == 'n':
                    result += '\n'
                elif json_str[0] == 't':
                    result += '\t'
                elif json_str[0] == 'b':
                    result += '\b'
                elif json_str[0] == 'f':
                    result += '\f'
                elif json_str[0] == 'r':
                    result += '\r'
                elif json_str[0] == '"':
                    result += '"'
                elif json_str[0] == '\\':
                    result += '\\'
                elif json_str[0] == 'u':
                    result += chr(int(json_str[1:5], 16))
                    json_str = json_str[5:]
                else:
                    raise ValueError("Invalid escape sequence")
            else:
                result += json_str[0]
            json_str = json_str[1:]
        if json_str[0] != '"':
            raise ValueError("Expected '\"'")
        return result

    def parse_token():
        json_str = json_str.strip()
        if json_str[0] == '{':
            return parse_object()
        elif json_str[0] == '[':
            return parse_array()
        elif json_str[0] == '"':
            return parse_string()
        elif re.match(r'^-?\d+(\.\d+)?$', json_str):
            return parse_value(json_str)
        elif json_str in ('true', 'false', 'null'):
            return parse_value(json_str)
        else:
            raise ValueError("Invalid JSON token")

    try:
        return parse_token()
    except Exception as e:
        raise ValueError("Invalid JSON") from e

