def parse_json(json_str):
    def parse_value(value):
        if value == 'true':
            return True
        elif value == 'false':
            return False
        elif value == 'null':
            return None
        elif value.startswith('"') and value.endswith('"'):
            return value[1:-1]
        elif value.isdigit():
            return int(value)
        elif value.startswith('-') and value[1:].isdigit():
            return int(value)
        elif '.' in value:
            return float(value)
        elif value.startswith('-') and '.' in value[1:]:
            return float(value)
        else:
            raise ValueError("Invalid JSON value")

    def parse_object(obj_str):
        obj_str = obj_str.strip()
