def parse_json(json_str):
    def parse_value(value):
        if value == 'true':
            return True
        elif value == 'false':
            return False
        elif value == 'null':
            return None
        elif value[0] == '"':
            return value[1:-1].replace('\\"', '"').replace('\\n', '\n').replace('\\t', '\t').replace('\\b', '\b').replace('\\f', '\f')
        elif value[0] == '[':
            return parse_array(value)
        elif value[0] == '{':
            return parse_object(value)
        else:
            try:
                return int(value)
            except ValueError:
                try:
                    return float(value)
                except ValueError:
                    raise ValueError("Invalid JSON value")

    def parse_array(array_str):
        array_str = array_str[1:-1]
        elements = []
        i = 0
        while i < len(array_str):
            if array_str[i] == ',':
                i += 1
                continue
            if array_str[i] == '[':
                j = array_str.find(']', i)
                elements.append(parse_value(array_str[i:j+1]))
                i = j + 1
            elif array_str[i] == '{':
                j = array_str.find('}', i)
                elements.append(parse_value(array_str[i:j+1]))
                i = j + 1
            else:
                j = array_str.find(',', i)
                if j == -1:
                    j = len(array_str)
                elements.append(parse_value(array_str[i:j]))
                i = j + 1
        return elements

    def parse_object(object_str):
        object_str = object_str[1:-1]
        obj = {}
        i = 0
        while i < len(object_str):
            if object_str[i] == ',':
                i += 1
                continue
            key_end = object_str.find(':', i)
            if key_end == -1:
                raise ValueError("Invalid JSON object")
            key = parse_value(object_str[i:key_end])
            i = key_end + 1
            if object_str[i] != ':':
                raise ValueError("Invalid JSON object")
            i += 1
            value = parse_value(object_str[i:])
            obj[key] = value
            i = value.find(',')
            if i == -1:
                break
            i += 1
        return obj

    try:
        return parse_value(json_str.strip())
    except Exception as e:
        raise SyntaxError("Invalid JSON syntax") from e

