                pos += 1
                value = parse_value(parse_token())
                result[key] = value
                if json_str[pos] == ',':
                    pos += 1
                else:
                    break
            else:
                key = parse_value(parse_token())
                pos += 1
                if json_str[pos] != ':':
                    raise ValueError("Expected ':'")
                pos += 1
                value = parse_value(parse_token())
                result[key] = value
                if json_str[pos] == ',':
                    pos += 1
                else:
                    break
        pos += 1
        return result

    def parse_array():
        if json_str[pos] != '[':
            raise ValueError("Expected '['")
        pos += 1
        result = []
        while json_str[pos] != ']':
            value = parse_value(parse_token())
            result.append(value)
            if json_str[pos] == ',':
                pos += 1
            else:
                break
        pos += 1
        return result

    def parse_string():
        if json_str[pos] != '"':
            raise ValueError("Expected string")
        pos += 1
        start = pos
        while pos < len(json_str) and json_str[pos] != '"':
            pos += 1
        if pos == len(json_str):
            raise ValueError("Unterminated string")
        result = json_str[start:pos]
        pos += 1
        return result

    def parse_token():
        start = pos
        if json_str[pos] == '"':
