import re

def parse_json(json_str):
    # Helper function to parse a single value
    def parse_value(value):
        if value.strip().lower() == 'true':
            return True
        elif value.strip().lower() == 'false':
            return False
        elif value.strip().lower() == 'null':
            return None
        elif re.match(r'^-?\d+(\.\d+)?$', value):
            return float(value) if '.' in value else int(value)
        elif value[0] == '"' and value[-1] == '"':
            return value[1:-1].replace('\\"', '"').replace('\\\\', '\\')
        elif value[0] == '[' and value[-1] == ']':
            return parse_array(value[1:-1])
        elif value[0] == '{' and value[-1] == '}':
            return parse_object(value[1:-1])
        else:
            raise ValueError("Invalid JSON value")

    # Helper function to parse an array
    def parse_array(array_str):
        elements = array_str.split(',')
        return [parse_value(elem.strip()) for elem in elements]

    # Helper function to parse an object
    def parse_object(object_str):
        pairs = object_str.split(',')
        return {pair.split(':')[0].strip(): parse_value(pair.split(':')[1].strip()) for pair in pairs}

    # Remove any leading/trailing whitespace
    json_str = json_str.strip()

    # Check for valid JSON structure
    if json_str.startswith('{'):
        return parse_object(json_str)
    elif json_str.startswith('['):
        return parse_array(json_str)
    else:
        raise ValueError("Invalid JSON structure")

